tool_input.command:
"C:\\WINDOWS\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command '$repo = (Resolve-Path '"'.').Path
"'$targets = @('"'.pytest_cache', 'tmp', 'subdir/workbench/.pytest_cache', 'subdir/workbench/tmp')
foreach ("'$target in $targets) {
  $full = Join-Path $repo $target
  if (Test-Path -LiteralPath $full) {
    $resolved = (Resolve-Path -LiteralPath $full).Path
    if ($resolved -like "$repo*") { Remove-Item -LiteralPath $resolved -Recurse -Force } else { throw "Refusing to remove outside repo: $resolved" }
  }
}'
